// Package eligibility is the rewards platform's contract for eligibility conditions: plugins, written by growth
// teams in Go, Lua or TypeScript, that decide whether a member of a campaign's cohort qualifies for its reward. A
// campaign names several conditions; a user qualifies when every one says so. Each condition validates itself
// against the platform's [Limits] before it goes live. condition_plg.go is generated by the line below (`go
// generate ./...`).
package eligibility

//go:generate go run github.com/heynemann/go-plg/cmd/plg gen Condition

import "context"

// User is what the platform's directory knows of the user a condition decides on.
type User struct {
	// ID identifies the user.
	ID string `json:"id"`
	// Country is the user's ISO 3166-1 alpha-2 country code.
	Country string `json:"country"`
	// Tier is the user's loyalty tier: "gold", "silver" or "bronze".
	Tier string `json:"tier"`
	// SpendCents is what the user spent in the last year, in cents.
	SpendCents int64 `json:"spendCents"`
	// Orders is how many orders the user placed in the last year.
	Orders int `json:"orders"`
}

// Subject is what a condition decides on: a user, for a campaign.
type Subject struct {
	// Campaign is the ID of the campaign asking.
	Campaign string `json:"campaign"`
	// User is the member of the campaign's cohort.
	User User `json:"user"`
}

// Decision is a condition's verdict on a subject.
type Decision struct {
	// Reason says why, for the condition's own tests and callers of Eligible: the platform records only its
	// length (campaign.reason_length on the member's span), never its text.
	Reason string `json:"reason"`
	// Eligible is whether the subject qualifies.
	Eligible bool `json:"eligible"`
}

// Limits is what the platform lets conditions require, the input of each condition's Validate
// (plg.WithValidation): a condition requiring more is rejected with an error issue before it goes live.
type Limits struct {
	// Countries are the countries the platform serves; a condition may only target these.
	Countries []string `json:"countries"`
	// MaxSpendCents is the largest yearly spend, in cents, a condition may require.
	MaxSpendCents int64 `json:"maxSpendCents"`
	// MaxOrders is the largest number of yearly orders a condition may require.
	MaxOrders int `json:"maxOrders"`
}

// Condition is an eligibility condition of campaigns.
//
// v2.0.0 breaks v1: Eligible became Decide, which decides on several subjects at once, so a platform built with v1
// cannot call a v2 condition (the module is example.com/rewards/v2, and plg skips its plugins as implementing
// another interface).
//
//plg:limits memory=128MiB timeout=5s pool=1..4
//plg:validation Limits
type Condition interface {
	// Decide decides whether each of subjects qualifies, a decision per subject in order.
	Decide(ctx context.Context, subjects []Subject) ([]Decision, error)
}
